var calc_output = [];

var start = parseFloat(start);
var stop = parseFloat(stop);
var packs = parseFloat(packs);
var ns = isNaN(parseFloat(ns)) ? 0 : parseFloat(ns);

var score = ((stop - start) - ns) * packs;

var warn;
if ((stop - start) < 0) {
    warn = 'Please ensure the starting age is before the stopping/current age.';
} else if ((stop - start) > 0 & (stop - start) < ns) {
    warn = 'Nonsmoking years must be less than total smoking years.' ;
}

score = score.toFixed(0);

if (score == 0) {
    score = '<1';
}

//results
if (score < 0){
    calc_output.push({
    name: 'mini',
    value: '',
    value_text: '',
    message: warn
    });
    calc_output.push({
        name: '10187_Pack Years_result',
        value: '',
        value_text: '',
        message: warn
    });
} else {
    calc_output.push({
    name: 'mini',
    value: score,
    value_text: 'pack years',
    message: 'More pack years correlates with higher lung disease risk'
    });
    calc_output.push({
        name: '10187_Pack Years_result',
        value: score,
        value_text: 'pack years',
        message: 'More pack years correlates with higher lung disease risk, including lung cancer. Consider screening with low-dose CT in adult patients ages 50-80 years with ≥20 pack year history of smoking and who currently smoke or have quit within the last 15 years. Counsel patients on smoking cessation.'   
    });
}
